# 2026-09-26 COWORKMILL 東京のコワーキング10施設
# 事実は各施設の公式サイト（または運営会社の公式発表）の範囲だけ。写真も同じページの直リンク
# 形式：steps の各要素は (ラベル, 見出し, [本文], [(写真番号, キャプション)])。写真番号は IMG30[slug] のキー
# _add の引数：(記事dict, 写真dict, 読み, 国コード, 編集部コメント2段落, 施設の公式サイトURL, メタタイトル用の拠点名)
IMG30 = {}
A30 = []
KANA30 = {}
COUNTRY30 = {}
ED30 = {}
OFFICIAL30 = {}
LOC30 = {}
# 掲載日。_add の前にこの値を書き換えてから足すと、その施設に掲載日が付く。一覧・トップの「新着順」はこの日付の新しい順（同じ日の中はファイルの順）
_ADDED = '2026-09-26'

def _add(a, imgs, kana, country, ed, official, loc):
    a.setdefault('added', _ADDED)
    A30.append(a)
    IMG30[a['slug']] = {str(k): v for k, v in imgs.items()}
    KANA30[a['slug']] = kana
    COUNTRY30[a['slug']] = country
    ED30[a['slug']] = ed
    OFFICIAL30[a['slug']] = official
    LOC30[a['slug']] = loc

# 重い写真の縮小用
def _w(u, w=1600):
    return 'https://wsrv.nl/?url=' + u.replace('https://', '') + '&w=' + str(w) + '&output=jpg&q=80'

# クエリ付きURL用（内側のURLを丸ごとエンコードする）
from urllib.parse import quote as _q
def _wq(u, w=1600):
    return 'https://wsrv.nl/?url=' + _q(u.replace('https://', ''), safe='') + '&w=' + str(w) + '&output=jpg&q=80'

