  ('02｜8F・9F 憩いのフロア','休みながら働くための階',['8階と9階は「憩い」のフロアです。個室のオフィスもこの2つの階にあります。','月額会員の BIRTHERs は月38,500円（入会金16,500円）で、24時間365日使えます。'],[(4,'8階「憩い」のフロア'),(5,'9階「憩い」のフロア')]),
  ('03｜1F BIRTH LAB','壁一面のウッドシェルフ、地下1階から2階までひと続きの空間',['同じビルの BIRTH LAB は「壁一面に張り出すウッドシェルフが特徴的で、天井高かつ、地下1階〜2階が1つの空間に収まっています」と公式サイトは説明します。1階のスタジオ、路面のテラス席、2階のラウンジ、半地下のキッチンで構成されます。','フロアごとに時間単位で借りられ、全フロアの貸切もできます。地域の人とビルで働く人が出会う入口です。'],[(6,'BIRTH LAB のスタジオ。壁一面のウッドシェルフ'),(7,'BIRTH LAB のキッチン')]),
