  ('02｜2F 会議室','打ち合わせとセミナーの階',['2階は会議室です。プロジェクターなどの設備があり、打ち合わせやセミナーに使えます。','カフェで作業をして、そのまま上の階で打ち合わせをする。移動のない使い方ができます。'],[(3,'館内の席')]),
  ('03｜3F シェアオフィス','会員の仕事場',['3階はシェアオフィスです。会員は7時から使え、早朝と夜の時間は無人で運営されています。','新宿駅から少し離れた西新宿7丁目という場所が、駅前の施設とは違う落ち着きを作っています。'],[(4,'館内の様子')]),
